const MilestonePulse: React.FC<{
  frame: number;
  eventFrame: number;
  x: number;
}> = ({frame, eventFrame, x}) => {
  const pulse = pulseAt(frame, eventFrame);
  if (pulse <= 0) return null;
  const scale = 0.7 + pulse * 1.25;

  return (
    <div
      style={{
        position: 'absolute',
        left: x - 70,
        top: HANDLE_Y - 70,
        width: 140,
        height: 140,
        borderRadius: '50%',
        border: `3px solid rgba(125,246,255,${0.44 * pulse})`,
        boxShadow: `0 0 ${38 * pulse}px rgba(0,231,255,${0.3 * pulse})`,
        opacity: pulse,
        transform: `scale(${scale})`,
      }}
    />
  );
};

