const NimbusHandle: React.FC<{
  frame: number;
  progress: number;
  handleX: number;
  speedEnergy: number;
}> = ({frame, progress, handleX, speedEnergy}) => {
  const bob = Math.sin((frame / FPS) * Math.PI * 2 * 0.5) *
    (3.5 + speedEnergy * 4.5);
  const tilt = Math.sin((frame / FPS) * Math.PI * 2 * 0.5 + 0.65) *
    (0.5 + speedEnergy * 1.1);
  const scaleX = 1 + speedEnergy * 0.045;
  const scaleY = 1 - speedEnergy * 0.032;
  const localPulse = Math.max(
    ...milestoneFrames.map((eventFrame) => pulseAt(frame, eventFrame)),
  );
  const completionBounce = interpolate(
    frame,
    [COMPLETION_FRAME, COMPLETION_FRAME + 4, COMPLETION_FRAME + 10, COMPLETION_FRAME + 18, COMPLETION_FRAME + 24],
    [0, 1, -0.18, 0.06, 0],
    {
      easing: Easing.out(Easing.cubic),
      extrapolateLeft: 'clamp',
      extrapolateRight: 'clamp',
    },
  );
  const completionLift = interpolate(
    frame,
    [COMPLETION_FRAME, COMPLETION_FRAME + 5, COMPLETION_FRAME + 12, COMPLETION_FRAME + 22],
    [0, -26, 5, 0],
    {
      easing: Easing.out(Easing.cubic),
      extrapolateLeft: 'clamp',
      extrapolateRight: 'clamp',
    },
  );
  const completionTurn = interpolate(
    frame,
    [COMPLETION_FRAME, COMPLETION_FRAME + 5, COMPLETION_FRAME + 12, COMPLETION_FRAME + 22],
    [0, -8, 3.5, 0],
    {
      easing: Easing.out(Easing.cubic),
      extrapolateLeft: 'clamp',
      extrapolateRight: 'clamp',
    },
  );
  const checkReveal = interpolate(
    frame,
    [COMPLETION_FRAME + 7, COMPLETION_FRAME + 14],
    [0, 1],
    {
      easing: Easing.out(Easing.back(1.8)),
      extrapolateLeft: 'clamp',
      extrapolateRight: 'clamp',
    },
  );

  return (
    <>
      <div
        style={{
          position: 'absolute',
          left: handleX - 144,
          top: HANDLE_Y - 112,
          width: 288,
          height: 224,
          borderRadius: '50%',
          background:
            'radial-gradient(ellipse, rgba(0,231,255,0.28) 0%, rgba(139,61,255,0.14) 45%, transparent 73%)',
          filter: `blur(${20 + localPulse * 9}px)`,
          opacity: 0.7 + speedEnergy * 0.18,
          transform: `scale(${1 + localPulse * 0.16})`,
        }}
      />

      <Img
        src={NIMBUS_ICON}
        style={{
          position: 'absolute',
          left: handleX - ICON_WIDTH / 2,
          top: HANDLE_Y - ICON_HEIGHT * ICON_ANCHOR_Y,
          width: ICON_WIDTH,
          height: ICON_HEIGHT,
          objectFit: 'fill',
          transformOrigin: `50% ${ICON_ANCHOR_Y * 100}%`,
          transform: `translateY(${bob + completionLift}px) rotate(${
            tilt + completionTurn
          }deg) scaleX(${scaleX + completionBounce * 0.1}) scaleY(${
            scaleY + completionBounce * 0.12
          })`,
          filter: [
            'drop-shadow(0 12px 10px rgba(0,0,0,0.34))',
            `drop-shadow(0 0 ${14 + speedEnergy * 11}px rgba(0,231,255,0.72))`,
            `drop-shadow(0 0 ${7 + localPulse * 9}px rgba(242,49,231,0.58))`,
          ].join(' '),
        }}
      />

      {checkReveal > 0 ? (
        <div
          style={{
            position: 'absolute',
            left: handleX + 42,
            top: HANDLE_Y - 142,
            width: 58,
            height: 58,
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            borderRadius: '50%',
            border: '3px solid rgba(248,252,255,0.92)',
            background:
              'linear-gradient(145deg, rgba(0,231,255,0.98), rgba(139,61,255,0.98))',
            boxShadow:
              '0 0 18px rgba(0,231,255,0.82), 0 0 34px rgba(139,61,255,0.48), inset 0 2px 2px rgba(255,255,255,0.54)',
            opacity: checkReveal,
            transform: `scale(${0.3 + checkReveal * 0.7}) rotate(${
              -18 + checkReveal * 18
            }deg)`,
            transformOrigin: '50% 50%',
          }}
        >
          <svg width="31" height="25" viewBox="0 0 31 25" fill="none">
            <path
              d="M3 12.5L11.2 21L28 3"
              stroke="#F8FCFF"
              strokeWidth="5"
              strokeLinecap="round"
              strokeLinejoin="round"
              pathLength="1"
              strokeDasharray="1"
              strokeDashoffset={1 - checkReveal}
            />
          </svg>
        </div>
      ) : null}

      {progress >= 0.997 ? (
        <div
          style={{
            position: 'absolute',
            left: handleX - 19,
            top: HANDLE_Y + 86,
            width: 38,
            height: 5,
            borderRadius: 6,
            backgroundColor: COLORS.cyanSoft,
            boxShadow: '0 0 18px rgba(125,246,255,0.9)',
            opacity: interpolate(progress, [0.997, 1], [0, 1], {
              extrapolateLeft: 'clamp',
              extrapolateRight: 'clamp',
            }),
          }}
        />
      ) : null}
    </>
  );
};

