const COMPLETION_SPARKS = [
  {angle: -168, distance: 154, size: 7, delay: 0, color: COLORS.cyanSoft},
  {angle: -148, distance: 188, size: 10, delay: 1, color: COLORS.cyan},
  {angle: -126, distance: 128, size: 6, delay: 0, color: COLORS.pearl},
  {angle: -104, distance: 174, size: 8, delay: 2, color: COLORS.violet},
  {angle: -78, distance: 142, size: 9, delay: 0, color: COLORS.cyanSoft},
  {angle: -52, distance: 194, size: 6, delay: 1, color: COLORS.magenta},
  {angle: -25, distance: 152, size: 8, delay: 2, color: COLORS.pearl},
  {angle: 4, distance: 184, size: 7, delay: 0, color: COLORS.cyan},
  {angle: 30, distance: 136, size: 10, delay: 1, color: COLORS.violet},
  {angle: 55, distance: 176, size: 6, delay: 0, color: COLORS.cyanSoft},
  {angle: 82, distance: 146, size: 8, delay: 2, color: COLORS.magenta},
  {angle: 112, distance: 190, size: 7, delay: 1, color: COLORS.pearl},
  {angle: 139, distance: 132, size: 9, delay: 0, color: COLORS.cyan},
] as const;

const CompletionBurst: React.FC<{frame: number; handleX: number}> = ({
  frame,
  handleX,
}) => {
  const local = frame - COMPLETION_FRAME;
  if (local < 0) return null;

  const flash = interpolate(local, [0, 2, 9, 24], [0, 1, 0.42, 0], {
    easing: Easing.out(Easing.cubic),
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp',
  });

  return (
    <AbsoluteFill style={{pointerEvents: 'none', overflow: 'hidden'}}>
      <div
        style={{
          position: 'absolute',
          left: handleX - 230,
          top: HANDLE_Y - 230,
          width: 460,
          height: 460,
          borderRadius: '50%',
          background:
            'radial-gradient(circle, rgba(248,252,255,0.3) 0%, rgba(0,231,255,0.18) 18%, rgba(139,61,255,0.08) 42%, transparent 68%)',
          opacity: flash,
          transform: `scale(${0.55 + (1 - flash) * 0.45})`,
          mixBlendMode: 'screen',
        }}
      />

      {[0, 5].map((delay, index) => {
        const ring = clamp((local - delay) / 19);
        const ringOpacity = interpolate(ring, [0, 0.14, 1], [0, 0.82, 0]);
        return (
          <div
            key={delay}
            style={{
              position: 'absolute',
              left: handleX - 76,
              top: HANDLE_Y - 76,
              width: 152,
              height: 152,
              borderRadius: '50%',
              border: `${index === 0 ? 4 : 2}px solid rgba(125,246,255,${ringOpacity})`,
              boxShadow: `0 0 ${22 + ring * 24}px rgba(0,231,255,${
                ringOpacity * 0.58
              })`,
              opacity: ringOpacity,
              transform: `scale(${0.65 + ring * (index === 0 ? 1.9 : 2.45)})`,
            }}
          />
        );
      })}

      {COMPLETION_SPARKS.map((spark) => {
        const travel = clamp((local - spark.delay) / 20);
        const easedTravel = travel * (2 - travel);
        const radians = (spark.angle * Math.PI) / 180;
        const x = Math.cos(radians) * spark.distance * easedTravel;
        const y =
          Math.sin(radians) * spark.distance * easedTravel +
          24 * travel * travel;
        const opacity = interpolate(
          travel,
          [0, 0.12, 0.68, 1],
          [0, 1, 0.72, 0],
        );
        return (
          <div
            key={`${spark.angle}-${spark.distance}`}
            style={{
              position: 'absolute',
              left: handleX - spark.size / 2,
              top: HANDLE_Y - spark.size / 2,
              width: spark.size,
              height: spark.size,
              borderRadius: spark.size > 8 ? 3 : '50%',
              backgroundColor: spark.color,
              boxShadow: `0 0 ${spark.size * 2.4}px ${spark.color}`,
              opacity,
              transform: `translate(${x}px, ${y}px) rotate(${
                spark.angle + travel * 110
              }deg) scale(${1 - travel * 0.32})`,
            }}
          />
        );
      })}
    </AbsoluteFill>
  );
};

const CompletionStatus: React.FC<{frame: number}> = ({frame}) => {
  const reveal = interpolate(
    frame,
    [COMPLETION_FRAME + 8, COMPLETION_FRAME + 16],
    [0, 1],
    {
      easing: Easing.out(Easing.cubic),
      extrapolateLeft: 'clamp',
      extrapolateRight: 'clamp',
    },
  );
  if (reveal <= 0) return null;

  return (
    <div
      style={{
        position: 'absolute',
        left: '50%',
        top: 786,
        display: 'flex',
        alignItems: 'center',
        gap: 12,
        color: COLORS.cyanSoft,
        fontFamily: 'Arial, Helvetica, sans-serif',
        fontSize: 23,
        fontWeight: 800,
        letterSpacing: 6,
        lineHeight: 1,
        textShadow:
          '0 0 10px rgba(0,231,255,0.88), 0 0 24px rgba(139,61,255,0.58)',
        opacity: reveal,
        transform: `translate(-50%, ${12 * (1 - reveal)}px) scale(${
          0.94 + reveal * 0.06
        })`,
        whiteSpace: 'nowrap',
      }}
    >
      <span
        style={{
          width: 8,
          height: 8,
          borderRadius: '50%',
          backgroundColor: COLORS.cyan,
          boxShadow: '0 0 14px rgba(0,231,255,0.95)',
        }}
      />
      SYNC COMPLETE
    </div>
  );
};

const FilmFinish: React.FC = () => (
  <AbsoluteFill style={{pointerEvents: 'none'}}>
    <AbsoluteFill
      style={{
        opacity: 0.12,
        backgroundImage:
          'repeating-linear-gradient(0deg, transparent 0px, transparent 3px, rgba(255,255,255,0.018) 4px)',
        mixBlendMode: 'screen',
      }}
    />
  </AbsoluteFill>
);

export const Motion: React.FC = () => {
  const frame = useCurrentFrame();
  const {fps} = useVideoConfig();
  const seconds = frame / fps;
  const progress = measuredProgressAt(seconds);
  const previous = measuredProgressAt(Math.max(0, (frame - 2) / fps));
  const speedPerSecond = ((progress - previous) * fps) / 2;
  const speedEnergy = clamp((speedPerSecond - 0.015) / 0.28);
  const handleX =
    HANDLE_START_X + progress * (HANDLE_END_X - HANDLE_START_X);

  return (
    <AbsoluteFill
      style={{
        overflow: 'hidden',
        backgroundColor: COLORS.midnight,
      }}
    >
      <Backdrop />
      <ProgressTrack progress={progress} frame={frame} handleX={handleX} />
      <NimbusHandle
        frame={frame}
        progress={progress}
        handleX={handleX}
        speedEnergy={speedEnergy}
      />
      <CompletionBurst frame={frame} handleX={handleX} />
      <PercentageDisplay frame={frame} progress={progress} />
      <CompletionStatus frame={frame} />
      <FilmFinish />
    </AbsoluteFill>
  );
};
